theorem ratSeries_hasSum_pow {f : PowerSeries ℚ} {z u : K}
    (hf : HasSum (fun k => (↑(coeff k f) : K) * z ^ k) u) (n : ℕ) :
    HasSum (fun k => (↑(coeff k (f ^ n)) : K) * z ^ k) (u ^ n)

theorem finiteEndpointPartition_monotone {n : ℕ} {a b : ℝ} {f : Fin n → ℝ}
    (hab : a ≤ b) (hf : Monotone f) (hI : ∀ k, f k ∈ Icc a b) :
    Monotone (finiteEndpointPartition a b f)

theorem finiteEndpointPartition_adjacent_lt {n : ℕ} {a b : ℝ} {f : Fin n → ℝ}
    (hab : a < b) (hf : StrictMono f) (hI : ∀ k, f k ∈ Ioo a b) :
    ∀ k < n + 1, finiteEndpointPartition a b f k < finiteEndpointPartition a b f (k + 1)

theorem finiteEndpointPartition_prefix {n : ℕ} {a b : ℝ} {f : Fin n → ℝ}
    (hab : a ≤ b) (hf : Monotone f) (hI : ∀ k, f k ∈ Icc a b)
    {k : ℕ} {u : ℝ}
    (hu : u ∈ Ioo (finiteEndpointPartition a b f k) (finiteEndpointPartition a b f (k + 1)))
    (j : Fin n) : f j ≤ u ↔ j.val < k

theorem phaseTransformedPolynomial_signVariations {e : ℝ}
    (he : (9 : ℝ) / 10 < e) (he1 : e < 1) :
    (phaseTransformedPolynomial e).signVariations = 1

theorem phaseTransformedPolynomial_positive_root_count {e : ℝ}
    (he : (9 : ℝ) / 10 < e) (he1 : e < 1) :
    (phaseTransformedPolynomial e).roots.countP (0 < ·) ≤ 1

theorem PhaseCoefficientSigns.positive_root_count {q : Polynomial ℝ}
    (hq : PhaseCoefficientSigns q) (hd : q.natDegree ≤ 6) :
    q.roots.countP (0 < ·) ≤ 1

theorem PhaseCoefficientSigns.positive_root_unique {q : Polynomial ℝ}
    (hq : PhaseCoefficientSigns q) (hd : q.natDegree ≤ 6) {x y : ℝ}
    (hx : 0 < x) (hy : 0 < y) (hpx : q.eval x = 0) (hpy : q.eval y = 0) : x = y

